// Cobalto's DAP proxy: it sits between the client (VS Code or a script) and
// lldb-dap, and rewrites what is needed to debug COBOL compiled by
// GnuCOBOL as if it were COBOL:
//  - variables and evaluate: b_NNN -> COBOL name, value formatted by libcob,
//    subordinate fields of a group as children;
//  - next / stepIn / stepOut: repeats the step while the top frame is
//    in the generated C or in the same COBOL statement (step per statement);
//  - stackTrace: frames in .c marked as generated code; frames in a
//    source generated by Cobalto mapped to the .cblt or to the original program;
//  - setBreakpoints: breakpoints set in the .cblt or in the original program
//    are moved to the generated source that actually gets compiled.
//
// This module only routes: each concern lives in a module of its own
// (channel, stack, records, breakpoints, variables) and they share the
// session.

import * as path from 'path';
import { Breakpoints } from './breakpoints';
import { Channel } from './channel';
import { loadBuildMaps } from './cobol-map';
import { Layout } from './layout';
import { LineMap } from './line-map';
import { DapEvent, DapMessage, DapRequest } from './protocol';
import { Records } from './records';
import { ProxyOptions, Session } from './session';
import { Stack } from './stack';
import { Variables } from './variables';

export { ProxyOptions } from './session';

export class CobaltoDapProxy {
  private readonly ch: Channel;
  private readonly session: Session;
  private readonly stack: Stack;
  private readonly records: Records;
  private readonly breakpoints: Breakpoints;
  private readonly variables: Variables;

  constructor(toClient: (msg: DapMessage) => void, opts: ProxyOptions) {
    this.session = new Session(opts);
    this.ch = new Channel(toClient, opts, (ev) => this.onAdapterEvent(ev));
    this.stack = new Stack(this.ch, this.session);
    this.records = new Records(this.ch, this.session);
    this.breakpoints = new Breakpoints(this.ch, this.session, this.stack, this.records);
    this.variables = new Variables(this.ch, this.session, this.stack, this.records);
  }

  dispose(): void {
    this.ch.dispose();
  }

  // ------------------------------------------------------------ client
  handleClientMessage(msg: DapMessage): void {
    this.ch.trace('<-client', msg);
    if (msg.type !== 'request') {
      this.ch.toAdapter(msg);
      return;
    }
    const req = msg as DapRequest;
    try {
      switch (req.command) {
        case 'initialize':
          this.ch.forwardThen(req, (r) => {
            this.session.canReadMemory = r.body?.supportsReadMemoryRequest === true;
            this.session.canWriteMemory = r.body?.supportsWriteMemoryRequest === true;
          });
          break;
        case 'launch':
          this.onLaunch(req);
          break;
        case 'setBreakpoints':
          void this.breakpoints.onSetBreakpoints(req);
          break;
        case 'scopes':
          this.ch.forwardThen(req, (r) => this.stack.onScopesResponse(req, r));
          break;
        case 'variables':
          void this.variables.onVariables(req);
          break;
        case 'evaluate':
          void this.variables.onEvaluate(req);
          break;
        case 'setVariable':
          void this.variables.onSetVariable(req);
          break;
        case 'stackTrace':
          this.ch.forwardThen(req, (r) => this.stack.rewriteStack(r));
          break;
        case 'next':
        case 'stepIn':
        case 'stepOut':
          void this.stack.onStep(req);
          break;
        case 'disconnect':
        case 'terminate':
          this.stack.stopStepping();
          this.ch.toAdapter(req);
          break;
        default:
          this.ch.toAdapter(req);
      }
    } catch (e) {
      this.ch.log(`error in ${req.command}: ${String(e)}`);
      this.ch.toAdapter(req);
    }
  }

  private onLaunch(req: DapRequest): void {
    const a: Record<string, unknown> = { ...(req.arguments ?? {}) };
    const cwd = typeof a.cwd === 'string' && a.cwd ? path.resolve(a.cwd) : process.cwd();
    const program = typeof a.program === 'string' && a.program ? path.resolve(cwd, a.program) : path.join(cwd, 'build', 'cbltdrv');
    const suite = typeof a.suite === 'string' ? a.suite.toUpperCase() : undefined;
    if (a.formatValues === false) {
      this.session.formatValues = false;
    }
    for (const k of ['suite', 'prepare', 'lldbDapPath', 'formatValues', 'type', '__configurationTarget', '__sessionId']) {
      delete a[k];
    }
    a.program = program;
    a.cwd = cwd;
    const init = Array.isArray(a.initCommands) ? (a.initCommands as string[]) : [];
    a.initCommands = ['settings set target.inline-breakpoint-strategy always', ...init];
    const buildDir = path.dirname(program);
    this.session.maps = loadBuildMaps(buildDir, (s) => this.ch.log(s));
    this.session.lineMap = undefined;
    this.session.layout = undefined;
    this.session.suite = suite;
    if (suite) {
      this.session.lineMap = LineMap.load(path.join(buildDir, `${suite}.lines.json`), cwd, (s) => this.ch.log(s));
      this.session.layout = Layout.load(path.join(buildDir, `${suite}.layout.json`), (s) => this.ch.log(s));
    }
    this.ch.log(`launch: program ${program}, cwd ${cwd}, suite ${suite ?? '(not set)'}, maps ${this.session.maps.size}, line map ${this.session.lineMap ? 'yes' : 'no'}`);
    this.ch.toAdapter({ ...req, arguments: a });
  }

  // ------------------------------------------------------------ adapter
  private onAdapterEvent(ev: DapEvent): void {
    const body = (ev.body ?? {}) as { reason?: string; threadId?: number };
    if (ev.event === 'stopped') {
      this.stack.clear();
      this.variables.clear();
      this.records.clear();
      if (body.reason === 'step' && this.stack.stepsOn(body.threadId)) {
        void this.stack.continueStepping(ev);
        return;
      }
      this.stack.stopStepping();
      if (body.reason === 'breakpoint' && this.breakpoints.hasConditions) {
        void this.breakpoints.checkCondition(ev);
        return;
      }
    } else if (ev.event === 'continued' && this.stack.midStep) {
      return;
    } else if (ev.event === 'continued' && this.breakpoints.swallowContinued()) {
      return;
    } else if (ev.event === 'terminated' || ev.event === 'exited') {
      this.stack.stopStepping();
    }
    this.ch.send(ev);
  }
}
